insert into public.questions(id,category_id,difficulty,prompt,options,correct_index,explanation) values
('fb-ea75504c79f308f595cc6102',(select id from public.categories where name='Fútbol'),1,'¿Qué parte del cuerpo está prohibido usar deliberadamente para marcar un gol, incluso para el guardameta?',array['El pie izquierdo','La rodilla','La mano o el brazo','La cabeza'],2,'Un gol marcado directamente con la mano o el brazo no es válido, incluso si lo marca el guardameta. Un cabezazo sí puede ser válido.'),
('fb-6690abaab948bf2b129fe41d',(select id from public.categories where name='Fútbol'),2,'¿Qué indica normalmente el árbitro al señalar el centro del campo después de un gol válido?',array['Que terminó necesariamente el partido','Que se repetirá el penal','Que se reanudará con un saque inicial','Que habrá saque de esquina'],2,'Después de un gol, el equipo que lo recibió reanuda el juego con un saque inicial desde el centro.'),
('fb-ad8d40860db6a982f2f3d50d',(select id from public.categories where name='Fútbol'),3,'¿Qué decisión corresponde si un defensor toca por última vez el balón antes de que cruce completamente su línea de meta, sin entrar en la portería?',array['Saque de meta para su equipo','Saque inicial','Balón a tierra obligatorio','Saque de esquina para el adversario'],3,'Si el último toque es de un defensor y el balón cruza la línea de meta fuera de la portería, corresponde saque de esquina. Si lo toca un atacante, corresponde saque de meta.'),
('fb-bac6e5b4b36fd28cf6046698',(select id from public.categories where name='Videojuegos'),1,'¿Qué hace normalmente la opción Pausa en un juego de un solo jugador?',array['Mejorar el equipo automáticamente','Cerrar la cuenta','Detener temporalmente la acción','Borrar la partida'],2,'La pausa suspende temporalmente la acción para poder continuar después. En partidas en línea, abrir un menú no siempre detiene el juego.'),
('fb-26c875c2a570ffdc212c9719',(select id from public.categories where name='Videojuegos'),2,'¿Qué representa una habilidad de área?',array['Una acción que elimina el mapa','Un botón para guardar','Un efecto que alcanza una zona','Una habilidad que solo cambia el menú'],2,'Una habilidad de área afecta una región del escenario. Puede alcanzar varios objetivos si están dentro de esa zona.'),
('fb-4f8093869323f7be30d62bdb',(select id from public.categories where name='Videojuegos'),3,'¿Para qué sirve anticipar visualmente un ataque enemigo antes de que ocurra?',array['Impedir cualquier estrategia','Permitir que el jugador lo reconozca y responda','Garantizar que el jugador pierda','Ocultar todas las reglas'],1,'Una señal previa comunica la intención del enemigo. El jugador puede aprender el patrón y elegir entre defender, atacar o usar un recurso.'),
('fb-eb05ecccd12322c9491518db',(select id from public.categories where name='Películas'),1,'¿Qué se muestra normalmente en los créditos de una película?',array['Las respuestas de un examen','Los nombres de quienes participaron en su producción','Solo el precio del boleto','La contraseña del cine'],1,'Los créditos reconocen al reparto y al equipo técnico. También pueden incluir agradecimientos, licencias y otros datos de producción.'),
('fb-1c4c7b0beac319a1d3ea96f7',(select id from public.categories where name='Películas'),2,'¿Qué describe un primer plano de un personaje?',array['Un encuadre cercano que destaca su rostro','Una vista completa de una ciudad','La primera película de un director','Un listado de escenas'],0,'El primer plano acerca la cámara al rostro para destacar expresiones y emociones. Un plano general muestra más del entorno.'),
('fb-fdb8b2127135e37fd87e19a6',(select id from public.categories where name='Películas'),3,'¿Qué distingue principalmente un corte de montaje de un movimiento de cámara continuo?',array['El corte exige cambiar de actor','El corte elimina siempre el sonido','El corte solo existe en animación','El corte cambia de un plano a otro'],3,'Un corte une dos planos diferentes. Un movimiento continuo cambia el encuadre dentro de una misma toma, sin necesitar ese salto de montaje.'),
('fb-940c34af729d8ee1dba01e33',(select id from public.categories where name='Series'),1,'¿Qué significa que una serie sea animada?',array['Que sus imágenes crean movimiento mediante técnicas de animación','Que no puede tener diálogos','Que todos los personajes son animales','Que cada episodio es un documental'],0,'La animación crea la ilusión de movimiento a partir de imágenes sucesivas. Puede contar historias de cualquier género y para distintas edades.'),
('fb-7fa058f1816ba437546db913',(select id from public.categories where name='Series'),2,'¿Para qué se utiliza una trama secundaria?',array['Eliminar el desarrollo de personajes','Desarrollar un conflicto adicional al principal','Reemplazar todos los episodios','Mostrar únicamente anuncios'],1,'Una trama secundaria acompaña a la principal y puede desarrollar personajes o temas. Puede conectarse con el conflicto central sin sustituirlo.'),
('fb-5cb4c93392393d0b3ce4a23f',(select id from public.categories where name='Series'),3,'¿Qué caracteriza a un narrador poco fiable?',array['Su relato puede estar sesgado o ser inexacto','Siempre conoce todos los hechos','Nunca participa en la historia','Solo habla en los créditos'],0,'Un narrador poco fiable presenta una versión que puede contener errores, engaños o sesgos. El público debe contrastarla con otras pistas de la historia.'),
('fb-96e87419d6e8854652955e6b',(select id from public.categories where name='Historia'),1,'¿Qué estudia principalmente la arqueología?',array['Solo las enfermedades actuales','La programación de computadoras','Las sociedades a través de sus restos materiales','Solo las estrellas'],2,'La arqueología analiza objetos, construcciones y otros restos materiales para estudiar sociedades del pasado. No se limita a buscar tesoros.'),
('fb-1304cbbcecf582ea397dd41c',(select id from public.categories where name='Historia'),2,'¿Qué océano cruzó la expedición de Cristóbal Colón en 1492 para llegar al Caribe?',array['El océano Austral','El Atlántico','El Índico','El Pacífico'],1,'La expedición de 1492 partió de la península ibérica y cruzó el Atlántico hasta el Caribe. No llegó a Asia, aunque Colón creyó haber alcanzado sus proximidades.'),
('fb-851b663fbca69ebacc98d935',(select id from public.categories where name='Historia'),3,'¿Cuál de estos documentos sería una fuente primaria para estudiar una batalla del siglo XIX?',array['Una novela actual inspirada en ella','Un videojuego publicado recientemente','Un resumen escolar del siglo XXI','Una carta escrita durante la batalla por un participante'],3,'Una fuente primaria se produjo en el periodo o procede de un testigo de los hechos. Debe analizarse críticamente: ser contemporánea no garantiza que sea imparcial.'),
('fb-8e0a87214ae5ed5f0f0d3c51',(select id from public.categories where name='Geografía'),1,'¿Qué instrumento muestra la orientación hacia el norte magnético?',array['La balanza','El cronómetro','La brújula','El termómetro'],2,'La aguja de una brújula se orienta según el campo magnético terrestre. El norte magnético no coincide exactamente con el norte geográfico.'),
('fb-1e07aa70fb608a9a37b0e4e0',(select id from public.categories where name='Geografía'),2,'En un mapa con escala 1:100 000, ¿qué distancia real representa 1 centímetro?',array['10 metros','1 metro','1 kilómetro','100 kilómetros'],2,'Un centímetro representa 100 000 centímetros reales. Al convertirlos a metros son 1 000 metros, es decir, un kilómetro.'),
('fb-09629bdeafd8058245e5bfcb',(select id from public.categories where name='Geografía'),3,'¿Por qué las estaciones del año son opuestas en los hemisferios norte y sur?',array['Porque la Luna cambia de tamaño','Porque el Sol se apaga en un hemisferio','Porque ambos hemisferios giran en sentidos contrarios','Por la inclinación del eje terrestre durante la traslación'],3,'La inclinación del eje hace que cada hemisferio reciba distinta iluminación a lo largo de la órbita. Cuando uno se inclina hacia el Sol, el otro se inclina en sentido opuesto.'),
('fb-2e914129d54f08c61c620f6f',(select id from public.categories where name='Ciencia'),1,'¿Qué órgano bombea la sangre por el cuerpo humano?',array['El pulmón izquierdo','El hígado','El corazón','El estómago'],2,'El corazón impulsa la sangre mediante sus contracciones. Los pulmones realizan el intercambio de gases, pero no sustituyen esa función de bombeo.'),
('fb-c59d3925a2fd0d2227e3ab6b',(select id from public.categories where name='Ciencia'),2,'¿Qué sucede con el agua líquida al congelarse a presión atmosférica normal?',array['Se convierte en plasma','Desaparece su materia','Se convierte en oxígeno puro','Se convierte en sólido'],3,'La congelación es el cambio de líquido a sólido. El agua sigue siendo agua: cambia su estado físico, no su composición química.'),
('fb-687b8a1302201b31ca18cafa',(select id from public.categories where name='Ciencia'),3,'¿Por qué un experimento compara un grupo tratado con un grupo de control?',array['Para evaluar el efecto del tratamiento frente a una referencia','Para garantizar el resultado deseado','Para evitar registrar datos','Para cambiar todas las variables a la vez'],0,'El control proporciona una referencia para distinguir el efecto del tratamiento de otros factores. Los grupos deben ser comparables y las demás condiciones controlarse.'),
('fb-a0e9a970a79676f1eb8a9f12',(select id from public.categories where name='Matemáticas'),1,'¿Cuánto es la cuarta parte de 20?',array['5','4','10','80'],0,'Encontrar la cuarta parte equivale a dividir entre cuatro: 20 ÷ 4 = 5. Multiplicar por cuatro daría 80, que es una operación distinta.'),
('fb-b204638e2d34b591ffdc7ca9',(select id from public.categories where name='Matemáticas'),2,'Un producto cuesta 200 pesos y tiene 15 % de descuento. ¿Cuánto pagas?',array['150 pesos','230 pesos','170 pesos','185 pesos'],2,'El 15 % de 200 es 30. Como es un descuento, se resta del precio: 200 − 30 = 170 pesos.'),
('fb-c95bb4953753bab207d4f001',(select id from public.categories where name='Matemáticas'),3,'Si 3x + 5 = 20, ¿cuánto vale x?',array['15','25','3','5'],3,'Primero resta 5 a ambos lados: 3x = 15. Después divide ambos lados entre 3 para obtener x = 5.'),
('fb-40a6fa4caa366c82e59d2a59',(select id from public.categories where name='Inglés'),1,'¿Qué significa la palabra inglesa window?',array['Ventana','Puerta','Mesa','Silla'],0,'Window significa ventana. Door corresponde a puerta, table a mesa y chair a silla.'),
('fb-9091853130a2e861e38d637c',(select id from public.categories where name='Inglés'),2,'¿Qué opción completa correctamente She ___ to school every day?',array['goes','go','going','gone'],0,'En presente simple, la tercera persona singular usa goes: She goes. Con I, you, we y they se utiliza go.'),
('fb-b69f5ac5d988c18fdae2173e',(select id from public.categories where name='Inglés'),3,'¿Qué oración expresa una situación hipotética presente con el segundo condicional?',array['I read yesterday.','I am reading now.','If I had more time, I would read more.','If I have time, I will read.'],2,'El segundo condicional combina if + pasado simple y would + verbo base. Describe una situación hipotética; el pasado no indica aquí necesariamente un hecho pasado.'),
('fb-e108c2ca9cba56d06bf72d14',(select id from public.categories where name='Programación'),1,'¿Para qué sirve principalmente una variable en un programa?',array['Para aumentar el tamaño de la pantalla','Para cargar físicamente una batería','Para reemplazar el teclado','Para almacenar un valor que el programa puede usar'],3,'Una variable permite identificar y utilizar un valor. Según el lenguaje y su declaración, ese valor puede cambiar durante la ejecución.'),
('fb-2268c68667c0540bfe56ecc7',(select id from public.categories where name='Programación'),2,'¿Qué estructura permite repetir instrucciones mientras se cumple una condición?',array['Una cadena vacía','Un nombre de archivo','Un bucle while','Un comentario'],2,'El bucle while comprueba una condición y repite su cuerpo mientras sea verdadera. Si la condición nunca cambia a falsa, puede producirse un bucle infinito.'),
('fb-5c69cb59c729eedfc5658351',(select id from public.categories where name='Programación'),3,'¿Qué significa que una operación de red sea idempotente?',array['Repetirla con la misma solicitud no añade efectos adicionales','Siempre se ejecuta sin conexión','Nunca puede fallar','Devuelve necesariamente un número'],0,'Una operación idempotente puede reintentarse sin duplicar su efecto. Por ejemplo, confirmar otra vez la misma recompensa no debería otorgarla dos veces.'),
('fb-579871e59e91c99c53f18d7c',(select id from public.categories where name='Cultura general'),1,'¿Qué objeto permite consultar la definición de una palabra?',array['Una calculadora','Un diccionario','Un termómetro','Una brújula'],1,'Un diccionario reúne palabras y sus significados. También puede indicar su pronunciación, origen y ejemplos de uso.'),
('fb-54c9bf8ac04eeb2c3a86fc86',(select id from public.categories where name='Cultura general'),2,'¿Qué sistema de escritura utiliza puntos en relieve para la lectura táctil?',array['Braille','Código Morse exclusivamente','Números romanos','Alfabeto cirílico'],0,'El braille representa símbolos mediante combinaciones de puntos en relieve. Se lee al tacto y puede representar letras, números y otros signos.'),
('fb-f984f16d595d9b69032341fb',(select id from public.categories where name='Cultura general'),3,'¿Qué diferencia una afirmación verificable de una opinión de gusto personal?',array['Toda opinión es siempre falsa','La afirmación verificable debe gustar a todos','Una opinión no puede expresarse por escrito','La afirmación verificable puede contrastarse con evidencia'],3,'Una afirmación verificable puede comprobarse mediante datos o fuentes. Un gusto personal, como preferir un color, expresa una valoración y no requiere una única respuesta universal.')
